'use strict';
const $=s=>document.querySelector(s), names={ru:'Русский',math:'Профмат',physics:'Физика'},colors={ru:'#aa773d',math:'#4b79bc',physics:'#8261aa'},KEY='mark-ege-v1';
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,parse=s=>new Date(s+'T12:00:00'),shift=(s,n)=>{let d=parse(s);d.setDate(d.getDate()+n);return iso(d)},monday=s=>shift(s,-((parse(s).getDay()+6)%7)),today=iso(new Date()),fmt=s=>parse(s).toLocaleDateString('ru-RU',{day:'numeric',month:'short'}),uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`;
const START_WEEK='2026-09-14';
let state={tasks:[],exams:[],weeks:[]},week=monday(today)<START_WEEK?START_WEEK:monday(today),editing=null,kind='task';
try{let saved=JSON.parse(localStorage.getItem(KEY));if(saved){if(!Array.isArray(saved.tasks)||!Array.isArray(saved.exams)||!Array.isArray(saved.weeks))throw Error();state=saved}}catch(e){$('#storage').textContent='Не удалось прочитать сохранение';}
function save(){if(window.markCloud?.active){window.markCloud.save();return}try{localStorage.setItem(KEY,JSON.stringify(state));$('#storage').textContent='Сохранено на этом устройстве'}catch(e){$('#storage').textContent='Сохранение недоступно';toast('Браузер не разрешает сохранение. Изменения останутся только до закрытия страницы.')}}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',4500)}
function ensureWeek(){if(week<START_WEEK||state.weeks.includes(week)||window.planEngine&&week>window.planEngine.settings(state).deadline)return;if(window.markCloud?.active&&!window.markCloud.writable)return;const template=[[0,'math','Занятие',50,0],[0,'physics','Занятие',50,0],[1,'ru','Занятие',45,0],[1,'math','Занятие',60,1],[2,'math','Занятие',50,0],[2,'physics','Занятие',50,0],[3,'ru','Занятие',45,0],[3,'physics','Занятие',75,1],[4,'math','Занятие',50,0],[4,'physics','Занятие',50,0],[5,'physics','Занятие',45,0]];state.tasks.push(...template.map(([d,subject,title,minutes,teacher])=>({id:uid(),date:shift(week,d),subject,title:teacher?'С преподавателем':'Самостоятельно',minutes,teacher:!!teacher,done:false,actual:0})));state.weeks.push(week);save()}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){ensureWeek();let tasks=state.tasks.filter(t=>t.date>=week&&t.date<=shift(week,6)),done=tasks.filter(t=>t.done).length,pct=tasks.length?Math.round(done/tasks.length*100):0;$('#percent').textContent=pct+'%';$('#bar').style.width=pct+'%';$('#doneText').textContent=`${done} из ${tasks.length} занятий`;let total=tasks.reduce((s,t)=>s+Number(t.actual||0),0);$('#time').innerHTML=`${Math.floor(total/60)} <small>ч</small> ${total%60} <small>мин</small>`;$('#planned').textContent=`По плану: ${tasks.reduce((s,t)=>s+Number(t.minutes),0)} мин`;$('#subjects').innerHTML=Object.entries(names).map(([k,n])=>{let a=tasks.filter(t=>t.subject===k);return `<div class="subjectrow"><span class="${k}">${n}</span><span>${a.filter(t=>t.done).length} / ${a.length} занятий</span></div>`}).join('');$('#weekLabel').textContent=`${fmt(week)} — ${fmt(shift(week,6))} · ${parse(week).getFullYear()}`;
$('#days').innerHTML=Array.from({length:7},(_,i)=>{let date=shift(week,i),a=tasks.filter(t=>t.date===date);return `<article class="day ${date===today?'current':''}"><div class="dayhead"><strong>${['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'][i]}</strong><span>${fmt(date)}${date===today?' · сегодня':''}</span></div>${a.map(t=>`<div class="task ${t.done?'done':''}"><div class="tasktop"><span class="badge ${t.subject}">${names[t.subject]}</span><button class="edit" data-edit="${t.id}" aria-label="Изменить или перенести: ${escape(names[t.subject]+' — '+(t.teacher?'С преподавателем':'Самостоятельно'))}">⋯</button></div><span class="tasktitle">${t.teacher?'С преподавателем':'Самостоятельно'}</span><div class="taskmeta">План: ${t.minutes} мин${t.teacher?' · Преподаватель':t.recoveryFor?' · Повторение':''}</div><div class="taskbottom"><label class="check"><input type="checkbox" data-done="${t.id}" ${t.done?'checked':''}> Сделано</label><label class="actualwrap">Факт: <input class="actual" type="number" min="0" max="1440" step="1" data-time="${t.id}" value="${t.actual||''}" placeholder="0" aria-label="Фактическое время: ${escape(names[t.subject]+' — '+(t.teacher?'С преподавателем':'Самостоятельно'))}"> мин</label></div></div>`).join('')||'<div class="emptyday">Свободный день<br>Отдохни или перенеси сюда занятие.</div>'}</article>`}).join('');renderExams();renderActivity();window.renderRoadmap?.();window.markCloud?.controls()}
function renderExams(){let exams=[...state.exams].sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id));$('#examList').innerHTML=exams.length?[...exams].reverse().map(e=>`<div class="examrow"><div><span class="${e.subject}">${names[e.subject]}</span><small>${parse(e.date).toLocaleDateString('ru-RU')}</small></div><strong>${e.score}</strong><button class="edit" data-exam="${e.id}" aria-label="Изменить результат">⋯</button></div>`).join(''):'<div class="empty">Пока нет результатов.<br>Добавь первый пробник, чтобы увидеть стартовую точку.</div>';if(!exams.length){$('#chart').innerHTML='<div class="empty">Динамика баллов<br><small>Здесь появится график твоих результатов</small></div>';return}let dates=[...new Set(exams.map(e=>e.date))],min=parse(dates[0]).getTime(),max=parse(dates.at(-1)).getTime(),x=d=>max===min?280:48+(parse(d).getTime()-min)/(max-min)*454,y=s=>200-s*1.7;let svg='<svg viewBox="0 0 550 250" role="img" aria-label="Динамика баллов пробников от 0 до 100. Точные результаты в списке рядом.">';for(let n=0;n<=100;n+=25)svg+=`<line x1="48" y1="${y(n)}" x2="510" y2="${y(n)}" stroke="#dfe7e2"/><text x="12" y="${y(n)+5}" font-size="13" fill="#65756d">${n}</text>`;for(let subject of Object.keys(names)){let a=exams.filter(e=>e.subject===subject);if(!a.length)continue;svg+=`<polyline points="${a.map(e=>`${x(e.date)},${y(e.score)}`).join(' ')}" fill="none" stroke="${colors[subject]}" stroke-width="2.5"/>`;svg+=a.map(e=>`<circle cx="${x(e.date)}" cy="${y(e.score)}" r="5" fill="${colors[subject]}"><title>${names[subject]}: ${e.score}, ${fmt(e.date)}</title></circle>`).join('')}svg+=`<text x="48" y="230" fill="#65756d" font-size="13">${fmt(dates[0])}</text>`;if(dates.length>1)svg+=`<text x="510" y="230" text-anchor="end" fill="#65756d" font-size="13">${fmt(dates.at(-1))}</text>`;$('#chart').innerHTML=svg+'</svg>'}
function openEditor(type,id){kind=type;editing=id||null;let isTask=kind==='task',item=id?(isTask?state.tasks:state.exams).find(t=>t.id===id):null;$('#form').reset();$('#dialogTitle').textContent=isTask?(id?'Изменить занятие':'Новое занятие'):(id?'Изменить результат':'Результат пробника');for(let s of ['minutes','teacher'])$('#'+s+'Field').hidden=!isTask;$('#scoreField').hidden=isTask;let f=$('#form').elements;f.minutes.required=isTask;f.score.required=!isTask;f.subject.value=item?.subject||'math';f.date.value=item?.date||(isTask?(today>=week&&today<=shift(week,6)?today:week):today);f.minutes.value=item?.minutes||50;f.teacher.checked=!!item?.teacher;f.score.value=item?.score??'';$('#delete').hidden=!id;$('#editor').showModal()}
$('#form').addEventListener('submit',e=>{e.preventDefault();let f=e.target.elements,isTask=kind==='task',list=isTask?state.tasks:state.exams,old=list.find(t=>t.id===editing),item={id:editing||uid(),subject:f.subject.value,date:f.date.value};if(!/^\d{4}-\d{2}-\d{2}$/.test(item.date))return;if(isTask){Object.assign(item,{title:f.teacher.checked?'С преподавателем':'Самостоятельно',minutes:Number(f.minutes.value),teacher:f.teacher.checked,done:old?.done||false,actual:old?.actual||0})}else item.score=Number(f.score.value);if(old)Object.assign(old,item);else list.push(item);save();$('#editor').close();render();toast(isTask&&monday(item.date)!==week?'Занятие сохранено на '+fmt(item.date):'Сохранено')});
$('#delete').onclick=()=>{if(!confirm(kind==='task'?'Удалить это занятие?':'Удалить результат пробника?'))return;let key=kind==='task'?'tasks':'exams';state[key]=state[key].filter(t=>t.id!==editing);save();$('#editor').close();render()};$('#close').onclick=()=>$('#editor').close();$('#addTask').onclick=()=>openEditor('task');$('#addExam').onclick=()=>openEditor('exam');$('#prev').onclick=()=>{week=shift(week,-7);render()};$('#next').onclick=()=>{week=shift(week,7);render()};$('#today').onclick=()=>{week=monday(today)<START_WEEK?START_WEEK:monday(today);render()};document.addEventListener('click',e=>{let b=e.target.closest('[data-edit],[data-exam]');if(b)openEditor(b.dataset.edit?'task':'exam',b.dataset.edit||b.dataset.exam)});document.addEventListener('change',e=>{let id=e.target.dataset.done||e.target.dataset.time;if(!id)return;let t=state.tasks.find(t=>t.id===id);if(e.target.dataset.done)t.done=e.target.checked;else{if(!e.target.checkValidity()){e.target.reportValidity();e.target.value=t.actual||'';return}t.actual=Number(e.target.value)}save();render()});window.addEventListener('storage',e=>{if(!window.markCloud?.active&&e.key===KEY&&e.newValue){try{let s=JSON.parse(e.newValue);if(Array.isArray(s.tasks)&&Array.isArray(s.exams)&&Array.isArray(s.weeks)){state=s;render()}}catch{}}});render();

function renderActivity(){let rows=Array.from({length:6},(_,i)=>{let start=shift(week,(i-5)*7),tasks=state.tasks.filter(t=>t.date>=start&&t.date<=shift(start,6)),by=Object.keys(names).map(k=>tasks.filter(t=>t.subject===k).reduce((s,t)=>s+Number(t.actual||0),0));return {start,tasks,by,total:by.reduce((a,b)=>a+b,0)}}),max=Math.max(60,...rows.map(r=>r.total));$('#activity').innerHTML='<div class="activityrows">'+rows.map(r=>'<div class="activityrow"><span>'+fmt(r.start)+'</span><div class="activitytrack" role="img" aria-label="'+r.total+' минут">'+r.by.map((v,i)=>'<span style="width:'+v/max*100+'%;background:'+colors[Object.keys(names)[i]]+'" title="'+Object.values(names)[i]+': '+v+' мин"></span>').join('')+'</div><strong>'+r.total+' мин</strong><small>'+r.tasks.filter(t=>t.done).length+' / '+r.tasks.length+' сделано</small></div>').join('')+'</div><div class="legend"><span class="ru">Русский</span><span class="math">Профмат</span><span class="physics">Физика</span></div>';}

window.renderStudyWeek=render;
